(x, y, t) => {
  const cx = 240, cy = 120;
  const flow = (px, py) => {
    const a1 = Math.sin(px*0.008+t*0.15)*2.5 + Math.cos(py*0.012-t*0.2)*2;
    const a2 = Math.cos(px*0.006+py*0.01+t*0.1)*1.8;
    return [Math.cos(a1)*4+Math.sin(a2+t)*2, Math.sin(a1)*4+Math.cos(a2-t)*2];
  };
  const [fx, fy] = flow(x, y);
  const sx = x + fx, sy = y + fy;
  const [fx2, fy2] = flow(x+50, y+50);
  const sx2 = x + fx2, sy2 = y + fy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 5],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 0],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+1)*40, 0.13, 1.8, 1]
  ];
  let aS=0, iS=0, cross=0;
  for (const [sX, sY, f, sp, id] of src) {
    const d1 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2 = Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    const w1 = Math.sin(d1*f-t*sp), w2 = Math.sin(d2*f*0.8-t*sp*0.9+0.5);
    aS += w1; iS += Math.sin(d1*f*0.7+t*sp*0.6+1.5);
    cross += w1*w2*Math.cos(id*1.047);
  }
  const n=8; const act=aS/n, inh=iS/n, crs=cross/n;
  const bg1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const bg2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((sx-sy)*0.1-t*2)*0.2;
  const moire = Math.sin(sx*0.19)*Math.sin(sy*0.19)*Math.sin((sx+sy)*0.13+t*0.7);
  const bg = (bg1+bg2)/2 + bg3 + bg4 + moire*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.4+sp3;
  const cell1 = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5);
  const cell2 = Math.tanh((Math.cos(sx*0.12+1)*Math.cos(sy*0.12-1)+Math.sin((sx-sy)*0.08-t*0.6)*0.4)*1.2);
  const cell = (cell1*0.6+cell2*0.4)*0.3;
  const diffusion = act - inh*0.7 + bg*0.3 + spiral + crs*0.4;
  const damped = diffusion*0.85 + Math.sin(diffusion*1.5+t)*0.15;
  const reaction = Math.tanh(damped*2.2);
  const edge = 1 - Math.min(1, Math.abs(reaction)*3)**0.5*0.3;
  const blend = reaction*0.65 + cell*0.35;
  const v = blend*0.5+0.5;
  const hShift = Math.sin(t*0.08)*0.15;
  const pal = [
    [5,10,45],[10,45,85],[15,85,115],[20,130,125],
    [60,165,120],[140,185,85],[195,175,60],[215,140,55],
    [210,105,65],[180,70,70],[120,40,75],[60,20,55],
    [25,12,48],[5,10,45]
  ];
  const shifted = v + hShift;
  const vs = ((shifted%1)+1)%1;
  const idx = vs*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const glow = Math.max(0, reaction-0.3)*0.6;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum + glow*40)*edge)|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum + glow*25)*edge)|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum + glow*15)*edge)|0
  ];
}
